window.__posterData({"id": "kevin-jabro", "name": "Kevin Jabro", "folder": "Week44_Poster_KevinJabro", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// The code did get a few lines longer but mostly made a few codes more organised and simplified \nlet dancing = false;\nlet posterText = [\"LET'S RAVE\", \"Kevin Jabro\"];\nlet disco;\n\n// Imported image\nasync function setup() {\n  createCanvas(600, 800);\n  disco = await loadImage(\"discoball.png\");\n}\n\n// The AI wrote \"draws\" in smaller functions\nfunction draw() {\n  background(0);\n  fill(255);\n\n  if (dancing) {\n    drawLasers();\n    image(disco, 240, 10, 120, 120);\n  }\n\n  drawText();\n  drawDanceFloor();\n  drawFigure();\n}\n\nfunction drawLasers() {\n  push();\n  strokeWeight(3);\n\n  for (let x = 0; x <= width; x += 100) {\n    if (random(1) < 0.5) {\n      stroke(random(100, 255), 0, random(100, 255));\n      line(300, 0, x, height);\n    }\n  }\n\n  pop();\n}\n\nfunction drawText() {\n  textAlign(CENTER);\n\n  if (!dancing) {\n    textSize(40);\n    text(posterText[0], 300, 75);\n\n    textSize(20);\n    text(\"Click to make him dance!\", 300, 710);\n  }\n\n  textSize(20);\n  text(posterText[1], 525, 775);\n}\n\nfunction drawFigure() {\n  circle(300, 200, 100);\n  fill(0);\n\n  // Draw the eyes\n  for (let x = 280; x <= 320; x += 40) {\n    circle(x, 190, 10);\n  }\n\n  fill(255);\n  rect(225, 250, 150, 225);\n  // The Ai wrote drawLeg instead of rect so it could make a function for them. \n  drawLeg(225, 1);\n  drawLeg(330, -1);\n\n  // AI wrote drawArm so both arms use the same code instead of repeating it as I did\n  drawArm(225, -35, -55);\n  drawArm(375, 35, 60);\n}\n\n// Step 2, this is the element I told the AI to do and similar to the drawArm's code it made for the legs. \n\nfunction drawLeg(x, direction) {\n  push();\n  translate(x + 22.5, 475);\n\n  if (dancing) {\n    rotate(sin(frameCount * 0.2) * 0.12 * direction);\n  }\n\n  rect(-22.5, 0, 45, 150);\n  pop();\n}\n\n// Removed * 1 from rotation and changed the Arm's code with \"innerEdge\" \"outerEdge\", which I have'nt heard of before\nfunction drawArm(x, innerEdge, outerEdge) {\n  push();\n  translate(x, 250);\n\n  if (dancing) {\n    rotate(sin(frameCount * 0.2));\n  }\n\n  quad(0, 0, 0, 50, innerEdge, 160, outerEdge, 160);\n  pop();\n}\n\n// Toggle dancing\nfunction mousePressed() {\n  dancing = !dancing;\n}\n\n// Step 3, this it what the AI decided to add. It made a ring below my dancer and made pulse. I haven't used pulse before but I understand it. This was a improvment to the aestethics and didn't change the funtionality. During the critique session they told me that my poster was bit of a suprise and with this additional feature it's slighly more of a suprise now. \n\nfunction drawDanceFloor() {\n  if (dancing) {\n    push();\n    noFill();\n\n    let pulse = sin(frameCount * 0.2) * 15;\n\n    // Soft neon glow\n    stroke(200, 0, 255, 50);\n    strokeWeight(12);\n    ellipse(300, 630, 230 + pulse, 55 + pulse);\n\n    // Bright centre of the ring\n    stroke(200, 0, 255);\n    strokeWeight(3);\n    ellipse(300, 630, 230 + pulse, 55 + pulse);\n\n    pop();\n  }\n}\n\n", "assets": {"discoball.png": {"mime": "image/webp", "b64": ""}}});
